window.AUTH=window.AUTH||{};window.AUTH["21-954"]={"d":"21-954","id":"2021/21-954","n":"Biden v. Texas","briefs":[{"k":"petitioner","label":"Brief of petitioners Joseph R. Biden, Jr., President of the United States, et al.","date":"2022-03-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-954/218538/20220314173404979_21-954tsUnitedStates.pdf","side":"pet","n":68},{"k":"respondent","label":"Brief of respondent Texas","date":"2022-04-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-954/220543/20220407154851029_21-954%20Brief%20for%20Respondents_Biden%20v.%20Texas.pdf","side":"res","n":59},{"k":"reply","label":"Reply of petitioner Joseph R. Biden, Jr., President of the United States, et al.","date":"2022-04-19","url":"https://www.supremecourt.gov/DocketPDF/21/21-954/221358/20220419110117779_21-954rbUnitedStates.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us2r66_k537.pdf","tr":true,"items":[{"t":"case","label":"American Textile Mfrs. Inst., Inc. v. Donovan","cite":"452 U.S. 490","y":1981,"id":"1980/79-1429","sc":1,"sum":"The Court held that the language of the Occupational Safety and Health Act requires the Occupational Safety and Health Administration to engage in feasibility analysis but not a cost-benefit analysis.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"op":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"4, 26, 30, 32","1":"49","2":"11"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Citizens to Preserve Overton Park, Inc. v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"op":2,"sum":"Under § 4 (f) of the Department. of Transportation Act of 1966 and § 138 of the Federal-Aid Highway Act of 1968, the Secretary of Transportation may not authorize use of federal funds to finance construction of highways through public parks if a \"feasible and prudent\" alternative route exists. If no such route is available, he may approve construction only if there has been \"all possible planning to minimize harm\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 42, 43, 45","1":"29, 47"}},{"t":"case","label":"City of Chicago v. Morales","cite":"527 U.S. 41","y":1999,"id":"1998/97-1121","sc":1,"op":1,"sum":"The Court held that Chicago's Gang Congregation Ordinance was unconstitutionally vague and provided law enforcement officials too much discretion to decide what activities constitute loitering.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Cyan, Inc. v. Beaver County Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"op":6,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17, 43, 45","1":"43","2":"18, 19, 20, 21"}},{"t":"case","label":"DHS v. Regents of the Univ. of Cal.","cite":"140 S. Ct. 1891","y":2020,"id":"2019/18-587","sc":1,"op":10,"ar":1,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"17, 38, 39, 40, 42","1":"passim","2":"17, 18"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"op":1,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"3, 5, 22"}},{"t":"case","label":"Fisher v. Pension Benefit Guar. Corp.","cite":"994 F.3d 664","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/994/664/","op":1,"sum":"Rejecting argument that agency action was post hoc when it “was styled as a ‘final agency action’ and did not purport to justify a predetermined outcome”.","sumSrc":"brief:0","by":{"0":"39"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"I.A. v. Garland","cite":"2022 WL 696459","y":2022,"court":"D.C. Cir. Feb. 24","op":7,"ar":1,"sum":"Noting that “[w]hen a district court invalidates a rule under the [APA], it is not unusual for the agency to update the faulty rulemaking” while also seeking relief “in the court of appeals”.","sumSrc":"brief:0","by":{"0":"47"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"25","1":"23, 24"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"op":2,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"op":6,"ar":6,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"7, 23, 33","1":"passim, 17, 16","2":"12, 13"}},{"t":"case","label":"Kaplan v. Tod","cite":"267 U.S. 228","y":1925,"id":"scdb/1924-095","sc":1,"sum":"1. Section 217-2 of the Revised Statutes, by which naturalization of -parents extends to minor children \"if dwelling in the United States,\" does not apply where a child was rightly denied entry as a feeble-minded person and ordered deported but permitted, under special safeguards, to remain in this country with her father while the deportation was temporarily suspended because of the late war.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 32"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"op":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Leng May Ma v. Barber","cite":"357 U.S. 185","y":1958,"id":"1957/105","sc":1,"sum":"Her release on parole did not alter her status as an excluded alien; she was not \"within the United States,\" within the meaning of § 243 (h); and thus she was not eligible for the benefits of that section. Pp. 185-190. 241 F. 2d 85, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 6, 32","2":"11"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"op":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"0":"44, 47","2":"18"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2001,"id":"2000/99-7504","sc":1,"op":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"0":"19","1":"32"}},{"t":"case","label":"Mayorkas v. Innovation Law Lab","cite":"141 S. Ct. 2842","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2842/","sc":1,"op":4,"by":{"0":"9"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"op":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"0":"37","1":"9"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of the U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"op":6,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"41","1":"46"}},{"t":"case","label":"National Ass’n of Reversionary Prop. Owners v. Surface Transp. Bd.","cite":"158 F.3d 135","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/158/135/","op":1,"sum":"Describing the doctrine as an “exception to statutory limits on the time for seeking review of an agency decision” (alterations omitted).","sumSrc":"opinion","by":{"0":"14, 45, 46"}},{"t":"case","label":"Natural Res. Def. Council v. EPA","cite":"571 F.3d 1245","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/571/1245/","by":{"0":"46"}},{"t":"case","label":"Natural Res. Def. Council, Inc. v. United States Nuclear Regulatory Comm’n","cite":"680 F.2d 810","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/680/810/","by":{"0":"47"}},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"sum":"The act of March 3, 1891, c. 551, forbidding certain classes of alien immigrants to land in the United States, is constitutional and valid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"6, 26, 32"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"140 S. Ct. 1601","y":2020,"id":"2019/17-1268","sc":1,"op":2,"sum":"The Court held that the Foreign Sovereign Immunities Act (FSIA) applies retroactively, thereby permitting recovery of punitive damages against foreign states for terrorist activities occurring prior to the passage of the current version of the statute.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Public Citizen v. Nuclear Regulatory Comm’n","cite":"901 F.2d 147","y":1990,"url":"https://www.courtlistener.com/c/F.2d/901/147/","by":{"0":"46"}},{"t":"case","label":"Railroad Co. v. Hecht","cite":"95 U.S. 168","y":1877,"id":"scdb/1877-043","sc":1,"sum":"The Cairo and Fulton Railroad Company having been sued in the Circuit Court of Clay County, Arkansas, service was bad on the tenth day of September, 1873, by leaving a copy of the summons with a clerk of the company.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Committee","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"op":2,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Richbourg Motor Co. v. United States","cite":"281 U.S. 528","y":1930,"id":"scdb/1929-067","sc":1,"sum":"Where a person, discovered in the act of transporting liquor unlawfully, has been arrested and the transporting vehicle seized under § 26 of the National Prohibition Act, proceedings to forfeit the vehicle must be taken under that section, which protects innocent lienors, and will not lie under Rev. Stats. § 3450. P. 532. 34 F. (2d) 38 and 35 id. 928, reversed. CERTIORARI, 280 U. S. 549, and post, p. 707, to review …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"op":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"40"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"op":2,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 41","1":"47"}},{"t":"case","label":"Saxbe v. Bustos","cite":"419 U.S. 65","y":1974,"id":"1974/73-300","sc":1,"sum":"The Supreme Court held that even if workers did not intend to reside in the U.S., they were still entitled to the ability to do so. The Court noted that the practice was longstanding and had since Congress had impliedly approved it. Justice Byron R. White wrote a dissent, stating that the plain meaning of the statute did not allow foreign commuters to be considered “permanent residents”.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Southern Utah Wilderness Alliance v. Smith","cite":"110 F.3d 724","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/110/724/","by":{"0":"47"}},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"ar":3,"sum":"The Court ruled that Gonzales had no constitutionally-protected property interest in the enforcement of the restraining order, and therefore could not claim that the police had violated her right to due process.","sumSrc":"Oyez","by":{"0":"16, 29, 30, 31","1":"12, 16, 17, 18","2":"9, 11"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"op":6,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"United States v. Munsingwear, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"Weyerhaeuser Co. v. United States Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"op":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"10"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"6","1":"2, 32","2":"3"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(42)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 3, 35","2":"2"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)"],"by":{"0":"18"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(d)(5)","(d)(5)(A)","(d)(5)(B)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"18, 18, 18","2":"4, 14, 15, 16, 17"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(a)(1)","(b)","(b)(1)","(b)(2)","(b)(2)(A)","(b)(2)(C)","(b)(1)(A)(i)"],"stext":{"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","paras":[[0,"(a) Inspection"],[0,"(1) Aliens treated as applicants for admission"],[1,"An alien present in the United States who has not been admitted or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters) shall be deemed for purposes of this chapter an applicant for admission."],[0,"(2) Stowaways"],[1,"An arriving alien who is a stowaway is not eligible to apply for admission or to be admitted and shall be ordered removed upon inspection by an immigration officer. Upon such inspection if the alien indicates an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview under subsection (b)(1)(B). A stowaway may apply for asylum only if the stowaway is found to have a credible fear of persecution under subsection (b)(1)(B). In no case may a stowaway be considered an applicant for admission or eligible for a hearing under section 1229a of this title."],[0,"(3) Inspection"],[1,"All aliens (including alien crewmen) who are applicants for admission or otherwise seeking admission or readmission to or transit through the United States shall be inspected by immigration officers."],[0,"(4) Withdrawal of application for admission"],[1,"An alien applying for admission may, in the discretion of the Attorney General and at any time, be permitted to withdraw the application for admission and depart immediately from the United States."],[0,"(5) Statements"],[1,"An applicant for admission may be required to state under oath any information sought by an immigration officer regarding the purposes and intentions of the applicant in seeking admission to the United States, including the applicant's intended length of stay and whether the applicant intends to remain permanently or become a United States citizen, and whether the applicant is inadmissible."],[0,"(b) Inspection of applicants for admission"],[0,"(1) Inspection of aliens arriving in the United States and certain other aliens who have not been admitted or paroled"],[0,"(A) Screening"],[0,"(i) In general"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title, the officer shall order the alien removed from the United States without further hearing or review unless the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution."],[0,"(ii) Claims for asylum"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title and the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview by an asylum officer under subparagraph (B)."],[0,"(iii) Application to certain other aliens"],[0,"(I) In general"],[4,"The Attorney General may apply clauses (i) and (ii) of this subparagraph to any or all aliens described in subclause (II) as designated by the Attorney General. Such designation shall be in the sole and unreviewable discretion of the Attorney General and may be modified at any time."],[0,"(II) Aliens described"],[4,"An alien described in this clause is an alien who is not described in subparagraph (F), who has not been admitted or paroled into the United States, and who has not affirmatively shown, to the satisfaction of an immigration officer, that the alien has been physically present in the United States continuously for the 2-year period immediately prior to the date of the determination of inadmissibility under this subparagraph."],[0,"(B) Asylum interviews"],[0,"(i) Conduct by asylum officers"],[3,"An asylum officer shall conduct interviews of aliens referred under subparagraph (A)(ii), either at a port of entry or at such other place designated by the Attorney General."],[0,"(ii) Referral of certain aliens"],[3,"If the officer determines at the time of the interview that an alien has a credible fear of persecution (within the meaning of clause (v)), the alien shall be detained for further consideration of the application for asylum."],[0,"(iii) Removal without further review if no credible fear of persecution"],[0,"(I) In general"],[4,"Subject to subclause (III), if the officer determines that an alien does not have a credible fear of persecution, the officer shall order the alien removed from the United States without further hearing or review."],[0,"(II) Record of determination"],[4,"The officer shall prepare a written record of a determination under subclause (I). Such record shall include a summary of the material facts as stated by the applicant, such additional facts (if any) relied upon by the officer, and the officer's analysis of why, in the light of such facts, the alien has not established a credible fear of persecution. A copy of the officer's interview notes shall be attached to the written summary."],[0,"(III) Review of determination"],[4,"The Attorney General shall provide by regulation and upon the alien's request for prompt review by an immigration judge of a determination under subclause (I) that the alien does not have a credible fear of persecution. Such review shall include an opportunity for the alien to be heard and questioned by the immigration judge, either in person or by telephonic or video connection. Review shall be concluded as expeditiously as possible, to the maximum extent practicable within 24 hours, but in no case later than 7 days after the date of the determination under subclause (I)."],[0,"(IV) Mandatory detention"],[4,"Any alien subject to the procedures under this clause shall be detained pending a final determination of credible fear of persecution and, if found not to have such a fear, until removed."],[0,"(iv) Information about interviews"],[3,"The Attorney General shall provide information concerning the asylum interview described in this subparagraph to aliens who may be eligible. An alien who is eligible for such interview may consult with a person or persons of the alien's choosing prior to the interview or any review thereof, according to regulations prescribed by the Attorney General. Such consultation shall be at no expense to the Government and shall not unreasonably delay the process."],[0,"(v) \"Credible fear of persecution\" defined"],[3,"For purposes of this subparagraph, the term \"credible fear of persecution\" means that there is a significant possibility, taking into account the credibility of the statements made by the alien in support of the alien's claim and such other facts as are known to the officer, that the alien could establish eligibility for asylum under section 1158 of this title."],[0,"(C) Limitation on administrative review"],[2,"Except as provided in subparagraph (B)(iii)(III), a removal order entered in accordance with subparagraph (A)(i) or (B)(iii)(I) is not subject to administrative appeal, except that the Attorney General shall provide by regulation for prompt review of such an order under subparagraph (A)(i) against an alien who claims under oath, or as permitted under penalty of perjury under section 1746 of title 28, after having been warned of the penalties for falsely making such claim under such conditions, to have been lawfully admitted for permanent residence, to have been admitted as a refugee under section 1157 of this title, or to have been granted asylum under section 1158 of this title."],[0,"(D) Limit on collateral attacks"],[2,"In any action brought against an alien under section 1325(a) of this title or section 1326 of this title, the court shall not have jurisdiction to hear any claim attacking the validity of an order of removal entered under subparagraph (A)(i) or (B)(iii)."],[0,"(E) \"Asylum officer\" defined"],[2,"As used in this paragraph, the term \"asylum officer\" means an immigration officer who—"],[3,"(i) has had professional training in country conditions, asylum law, and interview techniques comparable to that provided to full-time adjudicators of applications under section 1158 of this title, and"],[3,"(ii) is supervised by an officer who meets the condition described in clause (i) and has had substantial experience adjudicating asylum applications."],[0,"(F) Exception"],[2,"Subparagraph (A) shall not apply to an alien who is a native or citizen of a country in the Western Hemisphere with whose government the United States does not have full diplomatic relations and who arrives by aircraft at a port of entry."],[0,"(G) Commonwealth of the Northern Mariana Islands"],[2,"Nothing in this subsection shall be construed to authorize or require any person described in section 1158(e) of this title to be permitted to apply for asylum under section 1158 of this title at any time before January 1, 2014."],[0,"(2) Inspection of other aliens"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the case of an alien who is an applicant for admission, if the examining immigration officer determines that an alien seeking admission is not clearly and beyond a doubt entitled to be admitted, the alien shall be detained for a proceeding under section 1229a of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1225?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":3,"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","tname":"Aliens and Nationality","by":{"0":"18, 18, 18, 18, 18, 18, 18","2":"passim, 13, 10, 3, 4, 9, 10, 12, 13, passim"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)","(a)(2)"],"stext":{"head":"§1226. Apprehension and detention of aliens","paras":[[0,"(a) Arrest, detention, and release"],[0,"On a warrant issued by the Attorney General, an alien may be arrested and detained pending a decision on whether the alien is to be removed from the United States. Except as provided in subsection (c) and pending such decision, the Attorney General—"],[1,"(1) may continue to detain the arrested alien; and"],[1,"(2) may release the alien on—"],[2,"(A) bond of at least $1,500 with security approved by, and containing conditions prescribed by, the Attorney General; or"],[2,"(B) conditional parole; but"],[1,"(3) may not provide the alien with work authorization (including an \"employment authorized\" endorsement or other appropriate work permit), unless the alien is lawfully admitted for permanent residence or otherwise would (without regard to removal proceedings) be provided such authorization."],[0,"(b) Revocation of bond or parole"],[0,"The Attorney General at any time may revoke a bond or parole authorized under subsection (a), rearrest the alien under the original warrant, and detain the alien."],[0,"(c) Detention of criminal aliens"],[0,"(1) Custody"],[1,"The Attorney General shall take into custody any alien who—"],[2,"(A) is inadmissible by reason of having committed any offense covered in section 1182(a)(2) of this title,"],[2,"(B) is deportable by reason of having committed any offense covered in section 1227(a)(2)(A)(ii), (A)(iii), (B), (C), or (D) of this title,"],[2,"(C) is deportable under section 1227(a)(2)(A)(i) of this title on the basis of an offense for which the alien has been sentence 1 to a term of imprisonment of at least 1 year, or"],[2,"(D) is inadmissible under section 1182(a)(3)(B) of this title or deportable under section 1227(a)(4)(B) of this title,"],[1,"when the alien is released, without regard to whether the alien is released on parole, supervised release, or probation, and without regard to whether the alien may be arrested or imprisoned again for the same offense."],[0,"(2) Release"],[1,"The Attorney General may release an alien described in paragraph (1) only if the Attorney General decides pursuant to section 3521 of title 18 that release of the alien from custody is necessary to provide protection to a witness, a potential witness, a person cooperating with an investigation into major criminal activity, or an immediate family member or close associate of a witness, potential witness, or person cooperating with such an investigation, and the alien satisfies the Attorney General that the alien will not pose a danger to the safety of other persons or of property and is likely to appear for any scheduled proceeding. A decision relating to such release shall take place in accordance with a procedure that considers the severity of the offense committed by the alien."],[0,"(d) Identification of criminal aliens"],[0,"(1) The Attorney General shall devise and implement a system—"],[1,"(A) to make available, daily (on a 24-hour basis), to Federal, State, and local authorities the investigative resources of the Service to determine whether individuals arrested by such authorities for aggravated felonies are aliens;"],[1,"(B) to designate and train officers and employees of the Service to serve as a liaison to Federal, State, and local law enforcement and correctional agencies and courts with respect to the arrest, conviction, and release of any alien charged with an aggravated felony; and"],[1,"(C) which uses computer resources to maintain a current record of aliens who have been convicted of an aggravated felony, and indicates those who have been removed."],[0,"(2) The record under paragraph (1)(C) shall be made available—"],[1,"(A) to inspectors at ports of entry and to border patrol agents at sector headquarters for purposes of immediate identification of any alien who was previously ordered removed and is seeking to reenter the United States, and"],[1,"(B) to officials of the Department of State for use in its automated visa lookout system."],[0,"(3) Upon the request of the governor or chief executive officer of any State, the Service shall provide assistance to State courts in the identification of aliens unlawfully present in the United States pending criminal prosecution."],[0,"(e) Judicial review"],[0,"The Attorney General's discretionary judgment regarding the application of this section shall not be subject to review. No court may set aside any action or decision by the Attorney General under this section regarding the detention or release of any alien or the grant, revocation, or denial of bond or parole."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1226?type=usc&year=mostrecent&link-type=html"},"head":"§1226. Apprehension and detention of aliens","tname":"Aliens and Nationality","by":{"0":"18, 18","2":"13, 13"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"18"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(5)"],"stext":{"head":"§202. Border, maritime, and transportation responsibilities","paras":[[0,"The Secretary shall be responsible for the following:"],[1,"(1) Preventing the entry of terrorists and the instruments of terrorism into the United States."],[1,"(2) Securing the borders, territorial waters, ports, terminals, waterways, and air, land, and sea transportation systems of the United States, including managing and coordinating those functions transferred to the Department at ports of entry."],[1,"(3) Carrying out the immigration enforcement functions vested by statute in, or performed by, the Commissioner of Immigration and Naturalization (or any officer, employee, or component of the Immigration and Naturalization Service) immediately before the date on which the transfer of functions specified under section 251 of this title takes effect."],[1,"(4) Establishing and administering rules, in accordance with section 236 of this title, governing the granting of visas or other forms of permission, including parole, to enter the United States to individuals who are not a citizen or an alien lawfully admitted for permanent residence in the United States."],[1,"(5) Establishing national immigration enforcement policies and priorities."],[1,"(6) Except as provided in part C of this subchapter, administering the customs laws of the United States."],[1,"(7) Conducting the inspection and related administrative functions of the Department of Agriculture transferred to the Secretary of Homeland Security under section 231 of this title."],[1,"(8) In carrying out the foregoing responsibilities, ensuring the speedy, orderly, and efficient flow of lawful traffic and commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/202?type=usc&year=mostrecent&link-type=html"},"head":"§202. Border, maritime, and transportation responsibilities","tname":"Domestic Security","by":{"0":"46, 48","2":"10"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)"],"by":{"0":"46, 48"}},{"t":"reg","label":"Exec. Order No. 14,010, § 4(a)(ii)(B), 86 Fed. Reg. 8269","url":"https://www.govinfo.gov/link/fr/86/8269","by":{"0":"9"}},{"t":"reg","label":"62 Fed. Reg. 444","url":"https://www.govinfo.gov/link/fr/62/444","by":{"0":"23"}},{"t":"reg","label":"62 Fed. Reg. 10,312","url":"https://www.govinfo.gov/link/fr/62/10312","by":{"0":"35"}},{"t":"reg","label":"84 Fed. Reg. 6811","url":"https://www.govinfo.gov/link/fr/84/6811","by":{"0":"8"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Ala. Ass’n of Realtors v. Dep’t of Health & Human Servs.","cite":"141 S. Ct. 2485","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2485/","sc":1,"by":{"1":"21, 22"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"sum":"The Court held that a covenant not to sue invalidates a company’s counterclaim for trademark enforcement.","sumSrc":"Oyez","by":{"1":"36, 38"}},{"t":"case","label":"Amanullah v. Nelson","cite":"811 F.2d 1","y":1987,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/811/1/","by":{"1":"33"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41","2":"16"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"op":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Brown v. Plata","cite":"563 U.S. 493","y":2011,"id":"2010/09-1233","sc":1,"sum":"The Court held that a court order requiring California to reduce its prison population to remedy unconstitutional conditions in its correctional facilities did not violate the Prison Litigation Reform Act.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Chevron, USA, Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Cruz-Miguel v. Holder","cite":"650 F.3d 189","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/650/189/","by":{"1":"2, 19, 32","2":"17"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"sum":"The Court held, 6-3, that the Immigration and Nationality Act does not deprive the federal courts of jurisdiction to grant habeas relief to aliens challenging their detention under section 1226(c) and, 5-4, that detention during removal proceedings is a constitutionally permissible part of that process.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"FBI v. Abramson","cite":"456 U.S. 615","y":1982,"id":"1981/80-1735","sc":1,"sum":"Information contained in records originally compiled for law enforcement purposes does not lose its Exemption 7 exemption where such information is reproduced or summarized in a new document prepared for other than law enforcement purposes, but continues to meet Exemption 7's threshold requirement of being compiled for law enforcement purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"op":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"1":"48","2":"18"}},{"t":"case","label":"FCC v. ITT World Commc’ns, Inc.","cite":"466 U.S. 463","y":1984,"id":"1983/83-371","sc":1,"sum":"The Government in the Sunshine Act, 5 U. S. C. §552b(b), requires that \"meetings\" of a federal agency be open to the public. Section 552b(a)(2) defines a \"meeting\" as \"the deliberations of at least the number of individual agency members required to take action on behalf of the agency where such deliberations determine or result in the joint conduct or disposition of official agency business.\" Members of petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"141 S. Ct. 1150","y":2021,"id":"2020/19-1231","sc":1,"op":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"46","2":"23"}},{"t":"case","label":"FDA v. Am. Coll. of Obstetricians & Gynecologists","cite":"141 S. Ct. 10","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/10/","sc":1,"by":{"1":"45"}},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"op":1,"sum":"1. Section 22 of the Internal Security Act of 1950, providing for the deportation of any alien who has been a member of the Communist Party at any time after entry, is constitutional-as here applied to a resident alien shown to have been willingly a member of the Communist Party from 1944 to 1946 although not shown to have been aware of its advocacy of violent overthrow of the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"1, 15"}},{"t":"case","label":"Getty v. Fed. Sav. & Loan Ins. Corp.","cite":"805 F.2d 150","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/805/150/","by":{"1":"10"}},{"t":"case","label":"Harper & Row Publishers, Inc. v. Nation Enters.","cite":"471 U.S. 539","y":1985,"id":"1984/83-1632","sc":1,"sum":"The Court held that The Nation's use of verbatim excerpts from the unpublished manuscript was not a fair use.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Herb v. Pitcairn","cite":"324 U.S. 117","y":1945,"id":"scdb/1944-123","sc":1,"by":{"1":"39","2":"21, 22"}},{"t":"case","label":"HollyFrontier Cheyenne Refin., LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"1":"11, 15, 45"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"op":1,"sum":"The Court held that a district court conducting pretrial proceedings pursuant to section 1407(a) has no authority to invoke section 1404(a) to assign a transferred case to itself for trial.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"1":"15, 26"}},{"t":"case","label":"Medellin v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Ne. Fla. Ch. of Associated Gen. Contractors of Am. v. City of Jackson","cite":"508 U.S. 656","y":1993,"id":"1992/91-1721","sc":1,"sum":"The majority determined that the association members' possible lack of fair opportunity as a consequence of the ordinance would have constituted injury. Since the association members would have competed for the reserved city contracts in the absence of the ordinance, the Court found that they did have standing and reversed the judgment of the Court of Appeals.","sumSrc":"Oyez","by":{"1":"13, 39"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Okla. Press Pub. Co. v. Walling","cite":"327 U.S. 186","y":1946,"id":"scdb/1945-112","sc":1,"sum":"1. The Fair Labor Standards Act, as applied to the business of publishing and distributing newspapers, does not violate the First or Fifth Amendment or exceed the power of Congress under the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Rufo v. Inmates of Suffolk County Jail","cite":"502 U.S. 367","y":1992,"id":"1991/90-954","sc":1,"sum":"The Court held that the court does not require a grievous wrong evoked by new and unforeseen change of facts in order to modify a consented decree.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"(ctd.): Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"sum":"The Court held that, under the Indian Self-Determination and Education Assistance Act, the government is required to pay all of the contract support costs incurred by a tribal contractor if payment of those costs would exceed the statutory cap on the appropriations available to pay them.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Sys. Fed’n No. 91, Ry. Emp. Dep’t, AFL- CIO v. Wright","cite":"364 U.S. 642","y":1961,"id":"1960/48","sc":1,"sum":"It erred in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Tennessee v. Dunlap","cite":"426 U.S. 312","y":1976,"id":"1975/75-95","sc":1,"sum":"Where respondent's employment as a technician was terminated under § 709 (e) (1) when he was separated from the Guard upon expiration of his enlistment, § 709 (e) (3)'s requirement of \"cause\" has no application, and hence § 709 (e) (3) cannot provide the foundation for a claim that the termination of respondent's employment and the allegedly arbitrary refusal to re-enlist him violated due process. Pp. 315-316. 514 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Tyler Pipe Indus., Inc. v. Wash. State Dep’t of Revenue","cite":"483 U.S. 232","y":1987,"id":"1986/85-1963","sc":1,"sum":"Washington imposes a business and occupation (B & 0) tax on the privilege of engaging in business activities in the State, including manufacturing in the State and making wholesale sales in the State. The measure of the wholesale tax is the gross proceeds of sales, and the measure of the manufacturing tax is the value of the manufactured product. However, under the B & 0 tax's \"multiple activities exemption,\" local …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Util. Air Regul. Grp. v. E.P.A.","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"18, 22"}},{"t":"case","label":"Washington v. Confederated Bands & Tribes of Yakima Indian Nation","cite":"439 U.S. 463","y":1979,"id":"1978/77-388","sc":1,"sum":"Section 6 of Pub. L. 280 authorizes the people of States whose constitutions or statutes contain organic law disclaimers of jurisdiction over Indian country to amend \"where necessary\" their constitutions or statutes to remove any legal impediment to assumption of such jurisdiction under the Act, notwithstanding the provision of any Enabling Act for the admission of the State, but provided that the Act shall not …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"op":2,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"1":"16, 17","2":"12"}},{"t":"case","label":"(ctd.): Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"op":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"1":"26","2":"6, 7"}},{"t":"const","label":"Article I, Section 8, Clause 4","clauses":[["naturalization-bankruptcy","Naturalization and Bankruptcy Clause"]],"text":"To establish an uniform Rule of Naturalization, and uniform Laws on the subject of Bankruptcies throughout the United States;","by":{"1":"14, 26"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 96-212","url":"https://www.govinfo.gov/link/statute/94/102","by":{"1":"32"}},{"t":"reg","label":"8 C.F.R. § 212.5","url":"https://www.ecfr.gov/current/title-8/section-212.5","subs":["(a)"],"by":{"1":"28"}},{"t":"case","label":"Arizona v. Biden","cite":"2022 WL 1090176","y":2022,"court":"6th Cir. Apr. 12","by":{"2":"9, 10, 11"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"op":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Delgado-Sobalvarro v. Attorney General","cite":"625 F.3d 782","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/625/782/","by":{"2":"13"}},{"t":"case","label":"Innovation Law Lab v. McAleenan","cite":"924 F.3d 503","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/924/503/","sum":"Interpreting Section 1225(b)(1)(A)(i) to preserve DHS’s discretion.","sumSrc":"brief:2","by":{"2":"10"}},{"t":"case","label":"Mission Product Holdings, Inc. v. Tempnology, LLC","cite":"139 S. Ct. 1652","y":2019,"id":"2018/17-1657","sc":1,"sum":"A bankruptcy debtor’s rejection of an executory contract under 11 U. S. C. §365 has the same effect as a breach of that contract outside bankruptcy; such an act thus cannot rescind rights that the contract previously granted.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4, 5"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"op":7,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"10"}},{"t":"case","label":"Schaffer ex rel. Schaffer v. Weast","cite":"546 U.S. 49","y":2005,"id":"2005/04-698","sc":1,"sum":"In a 6 to 2 ruling, the Supreme Court held that the party bringing the suit bears the burden of proof, whether that party is the parents or the school system. In the majority opinion, Justice Sandra Day O'Connor wrote that \"absent some reason to believe that Congress intended otherwise, ... we will conclude that the burden of persuasion lies where it usually falls, upon the party seeking relief.\".","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"2":"19"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)(2)","(a)(6)"],"by":{"2":"16, 12"}},{"t":"rule","label":"Fed. R. Crim. P. 60","url":"https://www.law.cornell.edu/rules/frcrmp/rule_60","subs":["(b)"],"by":{"2":"22"}}]};